const normSub = (s) => {
  let x = (s || "").toLowerCase().trim();
  const prefix = /^(the|college of|circle of|oath of|way of|path of|school of)\s+/;
  while (prefix.test(x)) x = x.replace(prefix, "");
  return x.replace(/\s+domain$/, "").trim();
};
